steps.action:
curl -s -X POST https://slack.com/api/users.list \
  -d "token=<TOKEN>" | python3 -c "
import json,sys
data = json.load(sys.stdin)
if data.get('ok'):
    for m in data['members']:
        name = m.get('name','')
        real_name = m.get('real_name','')
        if 'john' in name.lower() or 'john' in real_name.lower():
            print(m['id'], name, real_name)
else:
    print('Error:', data.get('error'))
"
